    )
    	select TTT.SEQNO, TTT.CREDIT_FLAG, TTT.CREDIT_MST_ID, TTT.PFLSH,(TTT.hapCreditAmt+NVL(TEMP1.hapCreditAmt,0)) hapCreditAmt,TTT.creditAmt,TTT.VDATE,TTT.CUSTOMER_ID,TTT.CREDIT_CONDITION,TTT.insitituteCode,TTT.createTime
    	   FROM (							
