SELECT T.CREDIT_AMT FROM CREDIT_LINES_PRE T
WHERE T.CREDIT_MST_ID = #{creditMstId,jdbcType=VARCHAR}
AND T.CUSTOMER_ID = #{customerId,jdbcType=VARCHAR}
AND #{tradedate,jdbcType=DATE} BETWEEN T.VDATE AND T.MDATE

SELECT T.SEQNO, T.CREDIT_FLAG creditFlag, T.CREDIT_MST_ID creditMstId, T.PFLSH,T.HAP_CREDIT_AMT hapCreditAmt, T.CREDIT_AMT creditAmt,MAX(T.VDATE) VDATE,T.CUSTOMER_ID customerId, T.TERM term FROM CREDIT_LINES T WHERE (((
T.CUSTOMER_ID =(SELECT decode(T2.Type_8,'${fzq}',T1.ISSUER,'${fck}',T1.ISSUER,'${fxml}',T1.FINANCIER,'${fhg}',#{dto.counterId,jdbcType=VARCHAR},T1.MANAGER) FROM FIN_PRODUCT T1 INNER JOIN FIN_PRODUCT_TYPE T2 ON T1.FINPROD_ID = T2.FINPROD_ID WHERE T1.FINPROD_ID = #{dto.finprodId,jdbcType=VARCHAR})
T.CUSTOMER_ID = #{parentCustomId,jdbcType=VARCHAR}
AND T.CREDIT_MST_ID = #{creditmstidJG,jdbcType=VARCHAR} ))
OR (
T.CUSTOMER_ID = (SELECT decode(T2.Type_8,'${fzq}',T1.ISSUER,'${fck}',T1.ISSUER,'${fxml}',T1.FINANCIER,'${fhg}',#{dto.counterId,jdbcType=VARCHAR},T1.MANAGER) FROM FIN_PRODUCT T1 INNER JOIN FIN_PRODUCT_TYPE T2 ON T1.FINPROD_ID = T2.FINPROD_ID WHERE T1.FINPROD_ID = #{dto.finprodId,jdbcType=VARCHAR})
T.CUSTOMER_ID = #{parentCustomId,jdbcType=VARCHAR}
AND T.CREDIT_MST_ID IN
#{item}
)
) AND T.VDATE = (select max(tt.vdate) from CREDIT_LINES tt where t.credit_mst_id = tt.credit_mst_id and t.customer_id = tt.customer_id and #{dto.tradeDate,jdbcType=DATE}>=tt.vdate) AND #{dto.tradeDate,jdbcType=DATE} >=T.VDATE AND T.MDATE >=#{dto.tradeDate,jdbcType=DATE} GROUP BY T.SEQNO,T.CREDIT_FLAG,T.CREDIT_MST_ID,T.PFLSH,T.HAP_CREDIT_AMT,T.CREDIT_AMT,T.CUSTOMER_ID, T.TERM

SELECT T1.RISK_WEIGHT FROM ( SELECT ASSET_TYPE_ONE, ASSET_TYPE_TWO, RISK_WEIGHT FROM ( SELECT ASSET_TYPE_ONE, ASSET_TYPE_TWO, RISK_WEIGHT, RANK() OVER(PARTITION BY ASSET_TYPE_ONE,ASSET_TYPE_TWO ORDER BY EFF_DATE DESC ) AS rowno FROM RISK_WEIGHT WHERE #{tradedate} >= EFF_DATE ) WHERE rowno=1 ) T1 where 1 = 1
AND T1.ASSET_TYPE_ONE = #{type1}
AND T1.ASSET_TYPE_TWO= #{type2}

		select trade_id
			from TRD_PRODUCT_DEAL  
 		    where b_trade_id = #{bTradeId}

		select CLD1.* from CREDIT_LINES_DEAL CLD1
		left join CREDIT_LINES CL1 on CL1.SEQNO = CLD1.SEQNO
		WHERE CL1.VDATE = (select max(VDATE) from CREDIT_LINES CL2 WHERE CL1.CREDIT_MST_ID = CL2.CREDIT_MST_ID AND CL1.CUSTOMER_ID = CL2.CUSTOMER_ID

			and CL2.vdate < #{vdate, jdbcType=DATE}

		)

			and CL1.CREDIT_MST_ID = #{creditMstId,jdbcType=VARCHAR}


			AND CL1.CUSTOMER_ID = #{customerId,jdbcType=VARCHAR}


            AND CL1.INSTITUTION_CODE = #{orgno,jdbcType=VARCHAR}

select CLD1.* from CREDIT_LINES_DEAL CLD1
left join CREDIT_LINES CL1 on CL1.SEQNO = CLD1.SEQNO
WHERE CL1.VDATE = (select max(VDATE) from CREDIT_LINES CL2 WHERE CL1.CREDIT_MST_ID = CL2.CREDIT_MST_ID AND CL1.CUSTOMER_ID = CL2.CUSTOMER_ID

	and CL2.vdate < #{vdate, jdbcType=DATE}

)

	and CLD1.trade_date < #{vdate, jdbcType=DATE}


	and CL1.CREDIT_MST_ID = #{creditMstId,jdbcType=VARCHAR}


	AND CL1.CUSTOMER_ID = #{customerId,jdbcType=VARCHAR}


	AND CL1.INSTITUTION_CODE = #{orgno,jdbcType=VARCHAR}

select CLD1.* from CREDIT_LINES_DEAL CLD1
left join CREDIT_LINES CL1 on CL1.SEQNO = CLD1.SEQNO
WHERE 1=1

	AND CL1.SEQNO = #{seqno,jdbcType=VARCHAR}


	and CLD1.trade_date < #{vdate, jdbcType=DATE}


	AND CL1.INSTITUTION_CODE = #{orgno,jdbcType=VARCHAR}

		select nvl(CL1.HAP_CREDIT_AMT,0) from CREDIT_LINES CL1
		WHERE CL1.VDATE = (select max(VDATE) from CREDIT_LINES CL2 WHERE CL1.CREDIT_MST_ID = CL2.CREDIT_MST_ID AND CL1.CUSTOMER_ID = CL2.CUSTOMER_ID

			and CL2.vdate < #{vdate, jdbcType=DATE}

		)

			and CL1.CREDIT_MST_ID = #{creditMstId,jdbcType=VARCHAR}


			AND CL1.CUSTOMER_ID = #{customerId,jdbcType=VARCHAR}


            AND CL1.INSTITUTION_CODE = #{orgno,jdbcType=VARCHAR}

		select count(1) from CREDIT_LINES CL
		where 1=1

			and CL.CREDIT_MST_ID = #{creditmstid,jdbcType=VARCHAR}


			and CL.CUSTOMER_ID = #{customerid,jdbcType=VARCHAR}


			AND CL.VDATE = (select max(tt.vdate)
			from CREDIT_LINES tt
			where CL.credit_mst_id = tt.credit_mst_id
			and CL.customer_id = tt.customer_id
			and  #{dealdate, jdbcType=DATE} >= tt.vdate)


			AND  #{dealdate, jdbcType=DATE} >=CL.VDATE
			and CL.mdate >= #{dealdate, jdbcType=DATE}


            AND CL.INSTITUTION_CODE = #{orgno,jdbcType=VARCHAR}

